        return grid

    # Detect background color
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find active rows
    active_rows = [i for i in range(len(grid)) if any(c != bg for c in grid[i])]

    if len(active_rows) < 4:
        return grid

