    blocks = []
    curr = [active_rows[0]]
    for r in active_rows[1:]:
        if r == curr[-1] + 1:
            curr.append(r)
        else:
            blocks.append(curr)
            curr = [r]
    blocks.append(curr)

    if len(blocks) < 2:
        return grid

    top_block = blocks[0]
    bot_block = blocks[1]

    if len(top_block) != len(bot_block):
        return grid

    W = len(grid[0])

    # Simple rule: For each row pair where top row has foreground at rightmost column,
    # change bottom row rightmost to 1. For Demo 2 with 2 columns->check if top row has 
    # 2 or more consecutive foreground pixels at right
    for i in range(len(top_block)):
        tr = top_block[i]
        br = bot_block[i]

        # Find consecutive foreground pixels at the right of top row
        consec = 0
        for c in range(W - 1, -1, -1):
            if grid[tr][c] != bg:
                consec += 1
            else:
                break

        # Change that many rightmost columns of bottom row to 1
        for c in range(W - consec, W):
            grid[br][c] = 1

    return grid
